let exact = ["sk_live_", "sk_test_", "AKIA", "AIza", "PRIVATE KEY", "Bearer "];
for k in exact {
  let hits = find_strings(k);
  for h in hits {
    if h.value.contains(k) {
      report("Secret key (" + k + ")", h.address, "HIGH", h.value);
    }
  }
}
let assign_keys = ["api_key", "apikey"];
for k in assign_keys {
  let hits = find_strings(k);
  for h in hits {
    let v = h.value;
    if v.len() <= 128 && (v.contains("=") || v.contains(":")) {
      report("Possible key (" + k + ")", h.address, "MEDIUM", v);
    }
  }
}
